Local Ltac fast_eassumption :=
  first [ lazymatch goal with
          | |- rw_cells _ ?M ?A _ => assert_fails (is_evar M); match goal with H : rw_cells _ M A _ |- _ => exact H end
          | |- ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
          | |- bytes_at _ ?M ?A _ => assert_fails (is_evar M); match goal with H : bytes_at _ M A _ |- _ => exact H end
          | |- u8arr _ ?M ?A _ => assert_fails (is_evar M); match goal with H : u8arr _ M A _ |- _ => exact H end
          end
        | eassumption ].
(* [comment removed for export] *)
Local Ltac fit_zsizes :=
  repeat match goal with
  | |- context [Z.of_nat (cells_size ?cs)] =>
      let v := eval cbn [cells_size csize length Nat.add Z.of_nat Pos.of_succ_nat Pos.succ] in (Z.of_nat (cells_size cs)) in
      lazymatch v with Z0 => idtac | Zpos _ => idtac end;     (* [comment removed for export] *)
      change (Z.of_nat (cells_size cs)) with v
  end.
(* [comment removed for export] *)
Local Ltac dj_lia ::=
  first [ let a := dj_subject in progress (dj_reveal_for a); lia
        | lia
        | match goal with K : hideL _ |- _ => unfold hideL in K; lia end ].
Definition zeros36 : list byte := repeat (Z_to_bv 8 0) 36.
Definition hc_cells (g : bool) (j52 pad : list byte) : list cell :=
  if g then [C8 (Z_to_bv 64 AVP_HTTP_ECAT); C8 (Z_to_bv 64 HTTP_CAT_ID); CB 36 zeros36; CB 4 pad]
  else [CB 52 j52; CB 4 pad].

Lemma zext32_lit : forall e, 0 <= e < 2^32 ->
  Z_to_bv 64 (bv_unsigned (Z_to_bv 64 (bv_unsigned (Z_to_bv 64 e) ≪ 32)) ≫ 32) = Z_to_bv 64 e.
Proof.
  intros e He. f_equal. rewrite (unsigned_lit e) by lia.
  rewrite Z.shiftl_mul_pow2 by lia. rewrite unsigned_lit by lia.
  rewrite Z.shiftr_div_pow2 by lia. rewrite Z.div_mul by lia. reflexivity.
Qed.

Lemma failed_flag_lit : forall e, 1 <= e < 2^64 ->
  Z_to_bv 64 (bv_unsigned (v_sltu (Z_to_bv 64 0) (Z_to_bv 64 e)) + 2) = Z_to_bv 64 3.
Proof.
  intros e He. rewrite v_sltu_b2z. rewrite (unsigned_lit 0) by lia. rewrite (unsigned_lit e) by lia.
  replace (0 <? e) with true by (symmetry; apply Z.ltb_lt; lia). cbn [Z.b2z]. rewrite (unsigned_lit 1) by lia. reflexivity.
Qed.

